export type LoadedProjectsConfig = ProjectsConfig & { configPath: string | null }

/**
 * Re-reads the registry at `configPath` when its file changed (inode, size or modification time): the new config,
 * or null when unchanged. The first call always reads, so a change between startup and then is not missed. A file
 * that cannot be read or is invalid throws once per change, and the caller keeps its last config.
 */
export function projectsConfigReloader(configPath: string): () => Promise<ProjectsConfig | null> {
  let seen: string | null = null
  return async () => {
    let stamp: string
    try {
      const info = await stat(configPath)
      stamp = `${info.ino}:${info.size}:${info.mtimeMs}`
    } catch (error) {
      stamp = `unreadable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}`
    }
    if (stamp === seen) return null
    seen = stamp
    if (stamp.startsWith('unreadable:')) throw new ProjectsConfigError(`Project registry ${configPath} could not be read (${stamp.slice('unreadable:'.length)}).`)
    return parseProjectsConfig(await readFile(configPath, 'utf8'), configPath)
  }
}

/** Unset or blank means an empty registry; an explicitly named file must exist and be valid. */
export async function loadProjectsConfig(env: NodeJS.ProcessEnv): Promise<LoadedProjectsConfig> {
  const setting = env[PROJECTS_CONFIG_ENV]?.trim()
  if (!setting) return { ...EMPTY_PROJECTS, configPath: null }
  const configPath = resolve(setting)
  let text: string
  try {
    text = await readFile(configPath, 'utf8')
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code
    const reason = code === 'ENOENT' ? 'does not exist' : `could not be read (${code ?? 'unknown error'})`
    throw new ProjectsConfigError(`Project registry ${configPath} ${reason}. Create it from config/projects.example.json or unset ${PROJECTS_CONFIG_ENV} for an empty Projects root.`)
  }
  return { ...(await parseProjectsConfig(text, configPath)), configPath }
}

export class RunStore {
  private current: ProjectsConfig
  private projectsById = new Map<string, ProjectConfig>()
  private syncing: Promise<void> | null = null
  private readonly options: Required<Omit<RunStoreOptions, 'warn' | 'refresh'>> & Pick<RunStoreOptions, 'warn' | 'refresh'>

  constructor(config: ProjectsConfig, options: RunStoreOptions = {}) {
    this.current = config
    this.index(config)
    this.options = {
      exportByteLimit: options.exportByteLimit ?? DEFAULT_EXPORT_BYTE_LIMIT,
      packetByteLimit: options.packetByteLimit ?? DEFAULT_PACKET_BYTE_LIMIT,
      artifactByteLimit: options.artifactByteLimit ?? DEFAULT_ARTIFACT_BYTE_LIMIT,
