import { readFile } from 'node:fs/promises'
const which = process.argv[2]
const mod = await import(which === 'base' ? '/tmp/claude-1000/-home-agentops-dev-md-manager/541817b2-200f-49c5-b924-e4e11cf0112a/scratchpad/s5review/base/server/projects.ts' : '/home/agentops/dev/mdm-ux-s5/server/projects.ts')
const cfg = await import(which === 'base' ? '/tmp/claude-1000/-home-agentops-dev-md-manager/541817b2-200f-49c5-b924-e4e11cf0112a/scratchpad/s5review/base/server/projectsConfig.ts' : '/home/agentops/dev/mdm-ux-s5/server/projectsConfig.ts')
const path = `${process.env.HOME}/.config/md-manager/projects.json`
const config = await cfg.parseProjectsConfig(await readFile(path, 'utf8'), path)
const store = new mod.RunStore(config)
const out: Record<string, unknown> = {}
for (const project of store.config.projects) for (const workflow of project.workflows) {
  const scope = store.scope(project.project_id, workflow.workflow_id)
